ALTER TABLE "event_requests" ADD COLUMN "completed_by_id" text;--> statement-breakpoint
ALTER TABLE "event_requests" ADD COLUMN "completed_by_name" text;--> statement-breakpoint
ALTER TABLE "event_requests" ADD COLUMN "completed_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "event_requests" ADD CONSTRAINT "event_requests_completion_matches_status" CHECK (("event_requests"."status"::text = 'completed' and "event_requests"."completed_by_id" is not null and btrim("event_requests"."completed_by_id") <> '' and "event_requests"."completed_by_name" is not null and btrim("event_requests"."completed_by_name") <> '' and "event_requests"."completed_at" is not null) or ("event_requests"."status"::text = 'cancelled' and (("event_requests"."completed_by_id" is not null and btrim("event_requests"."completed_by_id") <> '' and "event_requests"."completed_by_name" is not null and btrim("event_requests"."completed_by_name") <> '' and "event_requests"."completed_at" is not null) or ("event_requests"."completed_by_id" is null and "event_requests"."completed_by_name" is null and "event_requests"."completed_at" is null))) or ("event_requests"."status"::text not in ('completed', 'cancelled') and "event_requests"."completed_by_id" is null and "event_requests"."completed_by_name" is null and "event_requests"."completed_at" is null));